// generated by node scripts/gen-licenses.js from release-notes/*.md; do not edit
export const RELEASE_NOTES: Readonly<Record<string, string>> = {
  "0.1": "## What's new\n- Add a torrent from a magnet link or a .torrent file, and pick which files to download.\n- The Transfers screen shows each download's progress and speed, with pause, resume and remove.\n- Search your downloads from the Transfers screen.\n- Pick the folder where downloads are saved.\n- Manage the queue of waiting downloads.\n- See how much free space is left on the device.\n- Light haptic feedback on taps.",
  "0.10": "## What's new\n- Download any web link, not only torrents, with pause, resume and retry.\n- Open a finished link download from its row in Transfers.\n- Link downloads have their own filter in Transfers.\n- Allow this device to download from links on your own local network servers.\n\n## What's changed\n- Links shared from other apps wait for a tap before they are added.\n- The Assistant uses OpenRouter's free models by default, and you can pick another model.\n- The Assistant works better with TalkBack and large text.\n\n## What's fixed\n- Copying a download never overwrites a file that is already there.\n- Pause all now also pauses downloads that your rules had paused.\n- A link blocked by your network settings offers an Open settings button.",
  "0.11": "## What's new\n- The Assistant can browse new or popular torrents by kind and time period.\n- The Assistant can ask you a question before it acts.\n- A \"What the Assistant can do\" sheet lists its abilities.\n- Links in Assistant replies open Transfers with its filter, or Search with its query.\n- Pick a specific free OpenRouter model for the Assistant.\n\n## What's changed\n- The Assistant chat shows each step it takes.\n- The Assistant answers more briefly, and it does not say something is done until you confirm it.\n- The Assistant says when OpenRouter's free daily limit is reached.\n\n## What's fixed\n- The Assistant's text box stays above the keyboard.\n- A search for a title you already have points to that download instead of adding it again.\n- The Assistant ignores search results whose names try to give it instructions.",
  "0.12": "## What's new\n- A Browser screen with an address bar, back and reload. Its Files tray lists the videos, audio, images and documents on a page, so you can download one.\n- Ad blocking in the browser, with a switch to allow ads on a site, and an update button in Settings → Browser.\n- Save HLS and DASH streams as one file, after picking the quality and audio.\n- Follow a show from Search, and its new episodes appear in Feeds.\n- Open, Share and Open folder on a finished download's detail screen.\n\n## What's changed\n- Each tab icon plays a small pixel move when you select it.\n- Taps answer at once, and pause, resume and remove change the row immediately.\n- Transfers and Search scroll more smoothly.\n- Transfers stops refreshing constantly when nothing is moving.\n- The Assistant can rank results by audio language and subtitles.\n\n## What's fixed\n- A recycled row in Transfers no longer shows another torrent's time left.",
  "0.13": "## What's new\n- The + button opens one menu: paste or type a link, open a .torrent file, search, or open the browser.\n- The add screen takes ordinary web links as well as torrents. You can rename a link and choose where it saves before you add it.\n- Every download shows its size and progress, for example \"412 MB of 1.2 GB · 34%\".\n- Open folder is on every download in Transfers, and finished link downloads can be opened and shared like torrents.\n- On mobile data, the add screen tells you the size before you start.\n- Pick a font style in Settings: Clean, Retro or Mono.\n- New welcome screens, with a small train animation.\n\n## What's changed\n- Sizes read \"412 MB\" instead of \"412.0 MB\".\n- The speed at the top of Transfers now includes link downloads.\n\n## What's fixed\n- After a fresh install or clearing the app's storage, Maglev could open the browser instead of the welcome screens.\n- The download notification no longer disappears when only link downloads are running.\n- Paste link works on the empty Transfers screen.",
  "0.14": "## What's new\n- Choose your app icon from 20 designs in Settings → Appearance → App icon.\n- Show, hide and reorder the tabs in Settings → Appearance → Tabs. The browser can now have its own tab.\n- The Feeds tab shows how many new items are waiting.\n- Tap a search result to see its details before you add it.\n- \"Download now on mobile data\" starts one download while Wi-Fi only is on, and \"Resume anyway\" restarts one that your rules paused.\n\n## What's changed\n- Settings is grouped into App, Finding things, Downloads and Connection. Interface is now called Appearance, Bandwidth and Torrents & queue are one page called Speed & queue, and notifications have their own page.\n- Finished torrents stop sharing on mobile data. Turn on Settings → Network → Share on mobile data to keep sharing.\n- Transfers is one sorted list. Finished torrents that are still sharing show \"Done · Seeding\", and Clear finished is in the sort menu.\n- Messages such as \"Added\" now show on every screen, not only on Transfers.\n- Saving a file from the browser shows which folder it goes to, and tells you when you're on mobile data.\n- Settings use plainer words.\n\n## What's fixed\n- Closing the quality picker no longer clears the link you were adding.\n- Items marked new in Feeds stay marked until you've seen them, and Feeds refreshes when you open the tab.",
  "0.15": "## What's new\n- Each search result shows what kind of file it is (video, music, book, app, game) with an icon, and says how long ago it was uploaded.\n- Tap the search box to see your recent searches.\n- When a source needs a quick check, Search shows one line with a Fix button, and Settings → Search sources lists those sources at the top with a ? to tap.\n- Hold a tab and drag it to reorder your tabs in Settings → Appearance → Tabs.\n- A star ticket in Settings → About opens Maglev on GitHub.\n\n## What's changed\n- Search is calmer: before you search it shows only the box and categories, and results start right under one line with the count and sort. To see results from a single source, use Sort and filter.\n- While searching, one line and a thin bar show how many sources have answered.\n- The Browser button on Search is smaller, and hides when the Browser has its own tab.\n- The empty Transfers screen leads with Add a link, with Search and Browser underneath.\n- Settings shows a hint the first time that more settings are further down.\n\n## What's fixed\n- Dark app icon previews, such as Mono, no longer blend into the background.",
  "0.16": "## What's new\n- Filter the list in Settings → Search sources by category, such as Movies, Anime or Books.\n- The Browser tab icon now has its own little animation, like the other tabs.\n\n## What's changed\n- About is now the first row under App in Settings.\n- Settings shows its scrollbar, a stronger fade at the bottom, and a More below hint that stays until you've scrolled to the end once.\n- Closing a sheet, such as Sort and filter or the add menu, puts TalkBack back on the button that opened it.\n- TalkBack says what happened: \"Searching 28 sources\", the number of results when a search ends, \"Added\", \"Removed\" for a recent search, and where a tab moved after you reorder it.\n- The search progress is no longer read out on every count change.\n- Categories, sort and source choices are read as one pick-one group.\n- The recent searches list and the quick check line fade in instead of popping up.\n- Numbers that change, such as the search count and upload age, no longer shift as they update.\n\n## What's fixed\n- In the light theme, the text on the GitHub star ticket is easier to read.\n- The peer and tracker lists in a torrent's details keep TalkBack's place when they refresh.",
  "0.17": "## What's new\n- The Assistant shows a small \"Thinking…\" row while it works, so you can tell it hasn't stalled.\n- A dot on the Assistant tab tells you a reply finished while you were somewhere else.\n\n## What's changed\n- The Assistant keeps working when you switch tabs or leave the app.\n- The Steps list opens by itself while a step runs and shows live progress, such as \"Knaben answered · 12 of 28 sources\".\n- Each finished step keeps its detail, such as how many results came back.\n- The Assistant searches for just the title. Words like \"best\", \"movie\" or \"torrents\" are no longer part of the search.\n\n## What's fixed\n- Stop works right away, even while the Assistant is still connecting.\n- Asking for \"prime time\" now finds Primetime, and no longer shows other films that share one of its words.",
  "0.19": "## What's new\n- Share a magnet, a .torrent file or a file link to Maglev from any app. A small card shows what it is and adds it with one tap, without opening Maglev.\n- Turn on \"Add without asking\" in Settings → Downloads to skip the card. A web page still asks, and opens Maglev's browser to find videos on it.\n- Open .torrent files with Maglev from a file manager.\n- Watch for a title: Maglev checks every 1, 6 or 24 hours (Wi-Fi only unless you allow mobile data) and tells you when something new turns up. Start one from Search, or ask the Assistant.\n- Backup and restore in Settings: your settings, search sources, torrents and downloads in one file. API keys are never included.\n- Play a video while it downloads, from its card or its screen.\n- Maglev pauses downloads before the phone runs out of space (it keeps 500 MB to 1 GB free) and resumes them when space comes back. Free up space lists finished downloads you can delete.\n- Assistant chats are saved and come back after a restart. A reply cut off by the restart offers Retry.\n\n## What's changed\n- When something goes wrong on a screen, Maglev shows an error screen with Reload instead of closing. About → Copy crash report copies what happened, kept only on your phone.\n- \"Storage full\" looks the same on torrents and link downloads, with a Free up space button.\n- A torrent's size counts only the files you keep, to the byte.\n- Deleting a torrent and its files shows the real amount freed, including files you skipped.\n\n## What's fixed\n- A link shared to Maglev while it was closed is no longer lost.\n- A finished torrent no longer shows \"Files changed\" after Maglev restarts.\n- The Pause, Resume and Delete bar in Transfers no longer has extra space under it.\n- Play on a download paused for storage says to free up space, not to resume it.",
  "0.20": "## What's new\n- Search results show the full torrent name over two lines, so you can read the resolution, codec and release group before you add one. Pick 1, 2 or 3 lines, or the full name, in Settings → Search sources → Result name lines.\n- In the browser, each file Maglev finds shows its size. Streams show an estimate marked with \"~\", and \"—\" means the site doesn't say.\n- The browser's file list opens on Video when the page has one, names the page each file came from, and hides tiny files (tap \"hidden\" to see them).\n- Remove a file or clear the list, with Undo. \"Scan again\" brings back everything on the page.\n- Long-press a file to pick several and download them together.\n- Files you already have show \"In Transfers\", and the browser shows how many are downloading.\n- Save one download to a subfolder without changing where the others go.\n\n## What's changed\n- The total speed bar and Pause all button above your transfers are hidden by default. Turn them back on in Settings → Appearance → Speed totals. Pause all is still in the notification.\n- The browser's file list now shows only the files on the page you're looking at. It used to keep files from every page you opened.\n- Maglev no longer asks Android for the \"draw over other apps\" or fingerprint permissions. It never used them.",
  "0.21": "## What's new\n- The browser keeps a history of the pages you open. Open it from ⋮ → History, or from Settings → Browser → History. Search it, tap a page to open it again, or remove one page or every page from a site, with Undo.\n- As you type in the address bar, pages from your history show up underneath. Tap one to open it.\n- Clear history for the last hour, today, the last 7 days or all time.\n- \"Clear history when Maglev closes\" in Settings → Browser clears history when you close Maglev, and again when it next starts. It's off by default.\n- Turn off Save history to stop keeping new pages, or Suggest from history to hide the address bar suggestions.\n- History stays on your phone. It's not sent anywhere and it's not in backups. Pages older than 90 days are removed.\n\n## What's changed\n- The bar at the bottom of the browser is gone, so pages use the whole screen. Files and the downloading count float over the page instead.\n- The number of ads and trackers blocked on a page is now in the ⋮ menu, under the ads option.\n- Downloading a file or stream from the browser opens a smaller card over the page instead of a sheet across the screen.\n- Notices such as \"Added to Transfers.\" use the same dark card style as the rest of the app.\n- Clear browsing data lets you choose what to clear: history, cookies and site data, or cache.\n\n## What's fixed\n- After you started one download from the browser, the \"Added to Transfers.\" notice with View didn't appear.",
  "0.22": "## What's new\n- Tabs in the browser. Tap the number next to ⋮ to see your tabs, switch between them, open a new one or close them. Closing a tab, or all of them, can be undone for a few seconds. Your tabs come back after a restart.\n- Long-press a link or image to open it in a new tab or a background tab, copy it, share it or download it. Long-press a magnet link to add the torrent.\n- Pop-ups and redirects you didn't tap for now wait for you. A card says what the page is trying to open, with Open, Block and Always allow on this site. Settings → Browser → Pop-ups and redirects has Ask, Block without asking and Allow, and a list of sites you allowed.\n- Find in page, from ⋮. It shows how many matches there are, with up and down to move between them.\n- Text size for web pages, from ⋮ or Settings → Browser, from 50% to 200%.\n- Maglev can update itself. It checks for a new version once a day, and Settings → About has Check for updates. Choose whether Maglev only tells you, downloads on Wi-Fi and asks before installing (the default), or installs on its own. Android asks you to confirm the first update. If you installed Maglev from F-Droid, Obtainium or another store, that store keeps updating it.\n- Report a bug, in Settings → About, opens a GitHub issue with your Maglev version, Android version and phone already filled in.\n\n## What's changed\n- Result name lines moved from Search providers to Settings → Appearance, as \"Search results: name lines\".\n- A tab you aren't looking at is paused, so its videos and sounds stop until you go back to it.\n- With Save history off, open tabs aren't saved either. With \"Clear history when Maglev closes\" on, tabs are cleared too.\n- Links that open another app (for example a Play Store or maps link) now ask first, and only when you tapped them.\n- A pop-up you allow opens as a new tab. A few sign-in and payment pop-ups expect to report back to the page that opened them, and may not finish this way. If one gets stuck, use the site's own sign-in page.\n\n## What's fixed\n- A page could open many hidden windows at once and slow Maglev down. Now at most three are handled at a time and the rest are blocked.",
  "0.23": "## What's new\n- Tabs in the browser. Tap the number next to ⋮ to see your tabs, switch between them, open a new one or close them, with Undo. Your tabs come back after a restart.\n- Long-press a link or image to open it in a new tab or a background tab, copy it, share it or download it. Long-press a magnet link to add the torrent.\n- Pop-ups and redirects you didn't tap for now wait for you, with Open, Block and Always allow on this site. Settings → Browser → Pop-ups and redirects has Ask, Block without asking and Allow.\n- Find in page and text size, from ⋮ in the browser.\n- The browser keeps a history you can search, from ⋮ → History. Pages you visited show up as you type in the address bar. Clear the last hour, today, the last 7 days or everything, or turn on \"Clear history when Maglev closes\".\n- Maglev updates itself. It checks once a day, and Settings → About has Check for updates. Choose whether it only tells you, downloads on Wi-Fi and asks before installing (the default), or installs on its own. Android asks you to confirm the first update. Installs from F-Droid, Obtainium or another store keep updating through that store.\n- The ad block list, the search source addresses and the default trackers refresh once a day without an app update, including ad lists you added yourself. Settings → About → Updates has Check now for each.\n- Report a bug, in Settings → About, opens a GitHub issue with your Maglev version, Android version and phone filled in.\n\n## What's changed\n- The bar at the bottom of the browser is gone, so pages use the whole screen. Files and the downloading count float over the page.\n- Download, stream and batch cards in the browser are smaller and match the app's dark style. The number of ads blocked on a page moved to ⋮.\n- Clear browsing data lets you choose history, cookies and site data, or cache.\n- Result name lines moved from Search providers to Settings → Appearance.\n- A tab you aren't looking at is paused, so its video and sound stop until you go back to it.\n- Links that open another app (a Play Store or maps link, for example) ask first, and only when you tapped them.\n- A pop-up you allow opens as a new tab. A few sign-in and payment pop-ups expect to report back to the page that opened them and may not finish. If one gets stuck, use the site's own sign-in page.\n- Once in a while, after a download finishes, Maglev asks if you'd star it on GitHub. \"Not now\" waits a month, and \"Don't ask again\" means never.\n\n## What's fixed\n- After you started one download from the browser, the \"Added to Transfers.\" notice with View didn't appear.\n- A page could open many hidden windows at once and slow Maglev down. Now at most three are handled at a time.",
  "0.24": "## What's new\n- A new tab shows Recent: the last 6 pages you visited, newest first. Tap one to open it, or See all for the History screen. With Save history off, or nothing visited yet, a new tab looks as before.\n\n## What's changed\n- ⋮ in the browser works before a page is open. On a new tab it shows History and Browser settings; the page items (Find in page, Text size, Desktop site, ads and pop-ups) appear once a page loads.\n- Updated libraries and build tools.\n\n## What's fixed\n- History could only be opened from ⋮, and ⋮ didn't work on a new tab, so you couldn't reach your history until a page had loaded.",
  "0.25": "## What's new\n- Search your settings. Type \"wifi\", \"dark\" or \"sd card\" at the top of Settings and tap a result to open its page. Close typos work too.\n- A new Updates page holds app updates and the self-updating lists, so About is just about Maglev: the star, Report a bug, the website, the licence (GPL-3.0) and the release notes for your version.\n- Set a speed limit for one link download from its sheet. The limit stays after a restart.\n- Copy a link, open Maglev, and it offers to download it. Turn this off in Settings > Downloads if you don't want Maglev to read the clipboard.\n- Paste a bare info hash (40 or 32 characters) to add a torrent.\n- Failed downloads retry on their own after a delay you pick, up to 3 times, or keep trying. Expired links and full storage aren't retried.\n- Hide from gallery keeps photo and video apps from listing Maglev's downloads.\n- Four more accent colours: Violet, Blue, Amber and Mint.\n\n## What's changed\n- Sort and filter in Search has labelled sections, a toggle to hide torrents no one is sharing, and a count of what's shown. Picking a sort no longer closes it.\n- Result name lines moved from Appearance to Search sources.\n- Settings is regrouped into App, General, Finding things, Downloads, and Network and power. A new Downloads page holds adding downloads, retry for links, and what happens when downloads finish. Speed & queue is now called Speed and sharing.\n- Pink is now a magenta-pink, so it can't be mistaken for an error.\n- In Light mode the Maglev logo is drawn in dark ink.\n- The Settings list no longer shows a scrollbar all the time.\n\n## What's fixed\n- In Light mode the logo was light green on a light background and hard to see.\n- The Settings row said \"Search providers\" while its page said \"Search sources\".",
  "0.26": "## What's new\n- Big link downloads go faster: a file is split into 4 parts that download at the same time. Change it in Settings > Downloads > Parts per download (1, 2, 4 or 8), or for one download in its sheet. A server that can't do this gets one connection, as before.\n- Free e-books from Project Gutenberg and free audiobooks from LibriVox now show up in Search. They're switched on for everyone once; turn them off in Search sources. Adding one of these opens the link download screen, since they're plain files, not torrents.\n- Four more search sources, off until you turn them on in Search sources: ShowRSS (TV shows), DistroWatch (Linux), ACG.RIP (anime) and U3C3 (adult, hidden while Hide adult is on).\n- Each release on GitHub has a SHA256SUMS file, so you can check a downloaded APK with `sha256sum -c`.\n\n## What's changed\n- The Pirate Bay shows only uploaders it marks as VIP or trusted. Turn off Trusted uploaders only in Search sources to see everyone's uploads.\n\n## What's fixed\n- Maglev stopped with \"The connection port is already in use\" when another app, such as another torrent app, was using port 6881. It now starts on a free port and says so in Settings. Your saved port isn't changed.\n- Back on Search, Feeds or Settings closed the app. It now goes to Transfers, and Back on an inner screen goes to the previous one.\n- A paused video showed the same triangle on two buttons. Play now has its own video icon.\n- Tapping Settings very soon after opening the app could close it.",
  "0.27": "## What's new\n- Stats: see what you downloaded, day by day. Open it from Settings > App > Stats. A little train runs along the week; drag it to pick a day. Time spent and average speed count while a download runs, not only when it finishes. Nothing leaves your phone.\n- Stop waiting for peers after: a torrent that never starts, with no one sharing it, now gives up after 10 minutes, frees its place in the queue and shows \"No one is sharing this yet\" with Keep trying. Maglev tries it again every hour. Change the time, or pick Never, in Settings > Speed and sharing.\n- Maglev shows up as an external download manager in browsers built on Kiwi, and downloads it gets from them keep their file names.\n\n## What's changed\n- After a search, the result count says how many sources didn't respond. Tap it to see which ones and why.\n\n## What's fixed\n- Parts per download only worked with some servers. Many sites (any that run nginx) got one connection in 0.26; they now get all the parts you set.\n- A site that was down for maintenance showed \"Blocked by a bot check\". It now says \"Down for maintenance\".\n- A web link typed into Add torrent asked you to tap Get info twice.\n- On Android the keyboard covered the buttons in sheets such as New feed.",
  "0.30": "## What's new\n- Subtitles. Find and save subtitles for your videos, from 21 free sources, with no account. It works while a video is still downloading: Maglev matches by name, then checks for an exact fit once the file finishes. Tap the pencil to change the name it searches for. The subtitle is saved next to the video so players pick it up. If one is already there, you choose Replace or Keep both. Pick languages and sources in Settings > Finding things > Subtitles.\n- Get subtitles as you add. After you add a film or an episode from Search, the Added message offers Get subtitles. Add several quickly and they share one message. Get subtitles for 3 opens a list where you tick the ones you want, and each row shows the quality and size so two releases of the same film are easy to tell apart. The Add screens have a Subtitles switch for that add.\n- Get subtitles for new videos, in Settings > Subtitles. With it on, every video you add gets subtitles in your languages while Maglev is open, from Search, links, feeds or a shared magnet. A close match is never saved without you: the card shows a ? until you pick one.\n- Each download's page has a Subtitles row that says what happened in words (saved, close match, none found yet) with the one button that fits: Pick one, Edit name, Change or Cancel.\n- Link downloads have their own page, like torrents: progress, speed, where the file came from and where it's saved. If a link stops working, the page says why. Paste a new link to the same file and tap Update link to carry on from where it stopped.\n- Choose how much a download's page shows, in Settings > Appearance > Download page. Compact shows the speed and time left. Detailed adds amounts, connections and timing. Previews show both before you pick.\n- Transfers says why a download is held (Wi-Fi only, battery, schedule, storage full and more), with a button for that setting.\n- Swipe a row in Transfers right to pause or resume it, or left to remove it from the list. Files are kept. Turn it off in Settings > Appearance.\n- Each card in Transfers can show an icon for its file type. A torrent gets the icon of its biggest file. Turn it off in Settings > Appearance.\n- Search has a size range slider, to hide results that are too small or too big.\n- In the browser, swipe the address bar left or right to switch tabs, or down to see them all. Turn it off in Settings > Browser.\n- Backups can include your stats. Tick Include stats when you export.\n- Every setting can be found with Settings search.\n- After an update, a short window shows the main new feature. Turn it off in Settings > Updates.\n\n## What's changed\n- A card no longer says Downloading when nothing is arriving. Before any data comes in it says Connecting to peers, with how many it has found. When data stops for 5 seconds it says Waiting for peers. Links say Connecting to the server and Waiting for the server.\n- While data arrives, a card shows how much is done next to the speed, for example 320 MB of 2.1 GB · 2.1 MB/s.\n- When a download isn't moving, its page explains why: peers found and connected, trackers that replied, how long it has tried or when data last came in, and an Ask trackers again button.\n- The Added message after a one-tap add sits above the tab bar, so the results you're tapping don't jump. The add button turns into a spinner while it adds, then a ✓.\n- Every card in Transfers has one status line, so all cards are the same height.\n- The Downloads group in Settings is now called Transfers, like the tab. Its first page is Adding and finishing.\n- The browser blocks more tricks. A download a page starts by itself goes to the Files tray with a notice. Pages can't fill your Back history to keep you on them. Known crypto-mining scripts are blocked. Pages open over HTTPS when the site supports it, and fall back to HTTP if the site doesn't answer.\n- Undo after removing a row lasts as long as Android's accessibility timeout asks, and never less than 5 seconds.\n\n## What's fixed\n- In Search, a torrent you added and then removed from Transfers still showed as added. You can add it again now.\n- After Shut down, or after Maglev closed itself when downloads finished, adding a torrent failed with \"The download engine isn't running yet\". Maglev now starts the engine again when you add, resume or change something. If it can't, it says why and offers Start engine. Shut down still stays shut down until you do something.\n- Pause all and Resume all in the notification did nothing if Android had closed Maglev in the background. They now start the engine first, and both show when one transfer is running and another is paused.\n- Tapping a page in the browser could open pop-ups and pop-unders. A tap now opens a new window only for the link you tapped.\n- The Transfer details switch in Settings > Appearance didn't change anything. It's now Download page, and it does.\n- On a torrent's page, the timing row touched the boxes above it.\n- A finished link download's page showed a dash for Time left. It now says Done.\n- Maglev could fail to start after Clear data when files from an earlier install were still in the download folder.",
  "0.31": "## What's new\n- Subtitles for a whole season. See all lists one row per episode, like S02E01 · Title, with its size and what happened. Tap an episode to pick its subtitle. When episodes have a clear best match, Use the best match for 23 saves them all in one tap. A match is only saved when the title, season, episode and language agree; the rest stay for you to pick.\n- When a subtitle search or a torrent search finds nothing, it shows the sources you haven't turned on, with a button to turn them on.\n\n## What's changed\n- A finished torrent whose files changed on disk says Done · Files changed instead of stopping at 99%. Resume isn't offered for it; Recheck is the way out.\n- If Maglev can't resume a download, the message says why and offers Open.\n- Resume all skips downloads that need a Recheck first.\n- Amounts on narrow cards are shortened so the line fits.\n- A download that is still starting explains what it's waiting for.\n\n## What's fixed\n- On Android 13 to 15, Back closed the app from any screen. It goes back one screen again.\n- Files were changed kept coming back after Recheck. Android's media scanner and players change a file's date without changing the file; Maglev now only counts a change in size, and a Recheck that passes clears the warning for good.\n- On the Stats page, picking an earlier day jumped back to today after a second while something was downloading.\n- The Pixel Train city highlights the building of the day you picked, not always today's.",
  "0.32": "## What's new\n- Bookmarks in the browser. Choose Add bookmark from the page menu, and a bookmark icon in the address bar shows the page is saved. Bookmarks are on a new tab's start page, at the top of address-bar suggestions, and in Bookmarks (page menu or Settings → Browser), where you can search, rename, remove and move one to the top. Backups include them, and restoring adds them to the ones already on your phone.\n- A new tab opens on a start page with your bookmarks, the sites you visit most and recent pages.\n- Long-press a video on a page to download it or its stream.\n- Pull down on a page to reload it.\n- Clear this site's data, in the page menu, signs you out of one site and leaves the others alone.\n- Private browsing, in Settings → Browser. Maglev keeps no history and doesn't reopen your tabs. When you leave the browser, it clears the cookies and cached pages of the sites you visited. Site storage and third-party cookies can stay.\n- Dark pages, in Settings → Browser, darkens sites that only have a light look while your phone is in dark mode.\n- Select a link in any app and choose Download with Maglev from the text menu. You may find it under ⋮.\n- Tapping a copied web link opens the same one-tap download sheet as sharing it.\n- When Transfers is empty, it shows how to send a link from another app with Share.\n- Export debug log, in Settings → About, saves a log you can attach to a bug report. Links, cookies, passwords and tracker keys are removed first.\n\n## What's changed\n- Change folder on the add screens now changes the folder for that download only. Your default folder stays the same.\n- Torrent network options such as the port, DHT and the blocklist are under Settings → Network → Advanced. Changes apply as soon as you restart the downloader from the banner.\n- The blocklist row says whether the list is on, off or can't be read.\n- Downloads from the browser send the page's cookies, Referer and Origin on every redirect and stream request, so more sites accept them.\n- Speeds show 3 digits, so the numbers on a card stay put.\n- In Search, the result count comes first, with one short line about the sources under it.\n- Starting the app is faster, and the screen no longer flashes grey first.\n- The app is smaller.\n\n## What's fixed\n- Opening the same page twice from History now opens it again.\n- A site that refuses a link now says \"The site refused this link\" instead of asking you to sign in.\n- Link downloads continue after you switch between Wi-Fi and mobile data.\n- When a server limits how many parts it accepts, the download keeps its progress and goes on with fewer parts.\n- A link download with no network says No internet connection instead of Waiting for the server.\n- Not enough space on the add screens shows how much you need and how much is held for other downloads.\n- Feeds: Skip episodes I already have no longer skips the same episode number of another show. A show named only by a year, like 1923, keeps its name.\n- A shared web page opens in the Browser tab instead of opening a second copy of the app's tabs.\n- If restarting the downloader fails after a network change, Maglev tries again.\n- Swipe actions on Transfers rows no longer show at the edges while you aren't swiping.",
  "0.33": "## What's fixed\n- Search results no longer disappear after a search where some sources didn't respond. The sources line under the result count stays one line tall, and the results show below it.",
  "0.5": "## What's new\n- Search for torrents from the Search tab, with categories, sorting and a live list of sources.\n- Results from sources that are often unsafe carry a warning, and you confirm before adding one.\n- Set a speed limit for one torrent, and move a torrent's files to another folder.\n- Auto-download new items from feeds that match rules you set.\n- A finished download sends an alert that opens the torrent.\n- Choose which files to download in a torrent, with a priority for each.\n- A magnet link shows the peers found while it loads, and you can start now or choose files.\n- Free space is checked before a download starts.\n- On Android 16 and later, download progress shows as a Live Update in the notification.\n\n## What's changed\n- The app icon is new, and all icons use one pixel style.\n- Pause and resume respond at once, and speeds are smoothed.\n- Each file in a torrent shows its own state.\n\n## What's fixed\n- Very slow speeds no longer show \"undefined/s\".\n- A schedule's 0 (no limit) no longer overrides a real limit.\n- Speed limits hold more closely, without a full second of extra burst.\n- Search titles show characters such as & as normal text.",
  "0.6": "## What's new\n- Add or remove trackers on a torrent while it runs.\n- Save a torrent's .torrent file, or share it.\n- Remove file deletes that file's data and keeps the rest of the torrent downloading.\n- Torrents that list web servers can also download from those servers.\n- Search includes EZTV for TV shows, and SubsPlease and AnimeTosho for anime.\n\n## What's changed\n- Private torrents keep their trackers.",
  "0.8": "## What's new\n- An Assistant tab that can find and add torrents for you. It is off by default, so turn it on in Settings. Connect it with OpenRouter sign-in or your own key.\n- A new Maglev train logo on the app icon and in the app, with the train cruising in the Transfers header and during onboarding.\n- Search has more sources, including anime, games, books and regional sites.\n\n## What's changed\n- The provider settings in Search sit above the lists they change.\n- The Settings icon is a pixel cog.\n- The tab bar no longer shows a ripple when you tap a tab.\n\n## What's fixed\n- After you remove a file in the app, the Files changed notice no longer appears by mistake.\n- Icon buttons no longer show a square box when pressed.\n- The file selection bar on a torrent's detail screen wraps to two rows, so its labels fit.",
  "0.9": "## What's new\n- Tap the Maglev mark in the header or on the About screen to send the train across the screen and back, with a light haptic.\n\n## What's changed\n- The train animation is sleeker and fits small sizes better.",
  "1.0": "## What's new\n- Maglev 1.0: the first stable release.\n- Maglev now downloads almost any link. Share or paste a YouTube, X, Instagram or other video link, pick a quality, and Maglev saves the video. Video links are experimental: some sites may fail. If one does, tell us with Report a bug in Settings › About. Files, magnet links and torrents work as before.\n- In the browser, long-press a video on YouTube, X or Instagram and choose Download this video.\n- Maglev keeps its video-site support up to date by itself, once a day on Wi-Fi. See Settings → Updates → Video sites.\n- Tips, in Settings → Tips: 47 short tips by topic. Swipe between them or pick a topic.\n- Swipe the browser's address bar left or right to switch tabs.\n- Tapping the address opens a full-screen editor with this page, your bookmarks and recent pages. Back leaves it.\n- Site settings, from the padlock in the address bar or the page menu: ads, pop-ups and clearing this site's data in one place.\n- Pop-ups: a card asks before a site opens one. Block remembers the site, and each site can be set to Ask, Allow or Block. Blocked pop-ups lists what was stopped.\n- Block cookies from other sites in Settings → Browser → Privacy and site data, and Try https first in Settings → Browser → Advanced.\n\n## What's changed\n- The page menu is shorter: Back, Bookmark, Reload, Share and Forward on top, then Find in page, Desktop site, Site settings, Bookmarks, History and Browser settings. Text size is in Settings → Browser → General.\n- Browser settings are grouped into Browsing, Privacy and safety, Downloads, Your pages and More.\n- Pull to reload follows your finger smoothly and uses Maglev's colours.\n- The Transfers and Search tab icons have new animations.\n\n## What's fixed\n- Maglev now shows up in Firefox's list of download managers.\n- Links shared from more browsers are found, and when one can't be read, Maglev offers to copy the details for a bug report.\n- A shared link opens the page instead of being searched for.\n- Find videos on this page opens the page first, and selected text on dark pages is readable.\n- Downloads from servers that send the whole file in a partial reply now finish.\n- A link or video download without a name no longer shows \"Torrent\" in its notification.",
  "1.1": "## What's new\n- Long transfer names can be read in full. A transfer's page shows its whole name under the top buttons: up to 3 lines, then Show more. Select one transfer and its full name shows above Pause, Resume and Delete.\n- Settings → Appearance → Transfer name lines: choose 1, 2 or 3 lines on each card in Transfers, or Full name.\n- Share a link to a file Maglev doesn't recognise by its name, such as a .bin or .csv file, and Maglev asks the server first. If it's a file, you get the download with its name and size instead of the web page card.\n\n## What's changed\n- Maglev can now offer fix releases such as 1.1.1 in its updater, not only new versions such as 1.2.\n- \"Done in\" on a finished video download now includes the time spent joining the video and sound.\n\n## What's fixed\n- Opening Maglev from its icon no longer brings back the Add screen of a link you shared earlier and already added or closed.\n- The What's New card no longer opens over a link you just shared.\n- The start screen shows the Maglev train on Android 12 and later instead of a blank screen.\n- \"This waits for Wi-Fi.\" on Add a link and Add torrent now appears and disappears as Wi-Fi drops and comes back while the screen is open.\n- Choosing Custom for a speed limit opens the field with the keyboard up.\n- At large text sizes, menu labels, filter counts and torrent stats are no longer cut off.",
};
